package com.aistock.prediction.verification;
import com.fasterxml.jackson.databind.*;import java.util.*;import java.time.*;
public final class HttpVerificationMarketClient implements VerificationMarketClient {
 static final Set<String> SOURCE_ERRORS=Set.of("MARKET_USE_BINDING_MISMATCH","MARKET_USE_ALREADY_RELEASED","MARKET_VERSION_USE_BLOCKED","MARKET_USE_NOT_READY","MARKET_USE_UNAVAILABLE","SOURCE_BUSY","SOURCE_TIMEOUT","SOURCE_UNAVAILABLE","SOURCE_INVALID","ATTEMPT_EXPIRED","REALIZATION_RAW_UNAVAILABLE","REALIZATION_RAW_MISMATCH","REALIZATION_SOURCE_INVALID","REALIZATION_CALENDAR_INVALID","REALIZATION_ORIGIN_MISSING","REALIZATION_REQUEST_INVALID","REALIZATION_RECORD_INVALID","REALIZATION_OPERATION_CONFLICT","REALIZATION_PAYLOAD_TOO_LARGE");
 private final String base;private final VerificationDependencyHttp http;private final int prepareSeconds,readSeconds;
 public HttpVerificationMarketClient(String base,String token,ObjectMapper mapper){this(base,token,mapper,50,10);}
 HttpVerificationMarketClient(String base,String token,ObjectMapper mapper,int prepareSeconds,int readSeconds){this.base=base;this.http=new VerificationDependencyHttp(token,mapper);this.prepareSeconds=prepareSeconds;this.readSeconds=readSeconds;}
 public JsonNode prepare(VerificationRequest r,JsonNode snapshot){return prepare(r,snapshot,Instant.now().plusSeconds(90));}
 public JsonNode prepare(VerificationRequest r,JsonNode snapshot,Instant deadline){var effectiveDeadline=r.leaseUntil().isBefore(deadline)?r.leaseUntil():deadline;var i=snapshot.path("input");var body=new LinkedHashMap<String,Object>();body.put("operationId",r.operationId());body.put("instrumentId",i.path("instrumentId").asText());body.put("originDate",i.path("originDate").asText());body.put("targetDates",i.path("targetDates"));body.put("dueThrough",r.dueThrough());body.put("leaseUntil",effectiveDeadline);
  var receipt=data(http.call(base,"/internal/v1/market/realizations/prepare",body,remaining(effectiveDeadline,prepareSeconds)));if(!r.operationId().toString().equals(receipt.path("operationId").asText()))throw VerificationDependencyHttp.error("VERIFICATION_SOURCE_INVALID");if(!"AVAILABLE".equals(receipt.path("state").asText())){String code=receipt.path("errorCode").asText();throw VerificationDependencyHttp.error("RUNNING".equals(receipt.path("state").asText())?"SOURCE_BUSY":SOURCE_ERRORS.contains(code)?code:"VERIFICATION_SOURCE_INVALID");}
  String id=receipt.path("versionId").asText();if(!id.matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}"))throw VerificationDependencyHttp.error("VERIFICATION_SOURCE_INVALID");
  var evidence=data(http.call(base,"/internal/v1/market/realizations/"+id,null,remaining(effectiveDeadline,readSeconds)));if(!id.equals(evidence.path("realizationVersionId").asText()))throw VerificationDependencyHttp.error("VERIFICATION_SOURCE_INVALID");return evidence;
 }
 private Duration remaining(Instant deadline,int seconds){var remaining=Duration.between(Instant.now(),deadline);if(remaining.isNegative()||remaining.isZero())throw VerificationDependencyHttp.error("VERIFICATION_BUDGET_EXCEEDED");return remaining.compareTo(Duration.ofSeconds(seconds))<0?remaining:Duration.ofSeconds(seconds);}
 private JsonNode data(JsonNode n){if(!"OK".equals(n.path("code").asText())||!n.path("data").isObject())throw VerificationDependencyHttp.error("VERIFICATION_SOURCE_INVALID");return n.path("data");}
}
